package com.railflow.yardops.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="trains") public class Train { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private String trainNumber; private String origin; private String destination; private Instant departureAt; private Instant arrivalAt; private String status; @ElementCollection(fetch=FetchType.EAGER) private List<String> assignedRailcars=new ArrayList<>(); protected Train(){} public Train(String trainNumber,String origin,String destination,Instant departureAt,Instant arrivalAt,String status){this.trainNumber=trainNumber;this.origin=origin;this.destination=destination;this.departureAt=departureAt;this.arrivalAt=arrivalAt;this.status=status;} public UUID getId(){return id;} public String getTrainNumber(){return trainNumber;} public String getOrigin(){return origin;} public String getDestination(){return destination;} public Instant getDepartureAt(){return departureAt;} public Instant getArrivalAt(){return arrivalAt;} public String getStatus(){return status;} public List<String> getAssignedRailcars(){return assignedRailcars;} public void assignRailcar(String carNumber){if(!assignedRailcars.contains(carNumber))assignedRailcars.add(carNumber);} }